{"content":"#!/usr/bin/env python3
"""Comprehensive audit script: axe-core + metadata + screenshots for all Hotbox pages."""
import json
import os
import time
from datetime import datetime
from urllib.parse import urlparse

from playwright.sync_api import sync_playwright

SHOTS_DIR = "/root/hotbox-closer/audit/shots"
os.makedirs(SHOTS_DIR, exist_ok=True)

# Key pages to audit (filtering out CSS/JS/static assets, calendar param variants, booking sub-pages)
PAGES = [
    "https://hotboxsocial.co.uk/",
    "https://hotboxsocial.co.uk/benefits",
    "https://hotboxsocial.co.uk/about",
    "https://hotboxsocial.co.uk/gallery",
    "https://hotboxsocial.co.uk/events",
    "https://hotboxsocial.co.uk/calendar",
    "https://hotboxsocial.co.uk/contact",
    "https://hotboxsocial.co.uk/policies",
    "https://hotboxsocial.co.uk/privacy-policy",
    "https://hotboxsocial.co.uk/sessions",
    "https://hotboxsocial.co.uk/memberships",
    "https://hotboxsocial.co.uk/book-now",
    "https://hotboxsocial.co.uk/cookie-policy",
    "https://hotboxsocial.saunders-simmons.co.uk/",
    "https://hotboxsocial.saunders-simmons.co.uk/login",
    "https://hotboxsocial.saunders-simmons.co.uk/signup",
    "https://hotboxsocial.saunders-simmons.co.uk/account",
]

# Mobile viewport
MOBILE_VIEWPORT = {"width": 390, "height": 844}
DESKTOP_VIEWPORT = {"width": 1920, "height": 1080}

def slugify(url):
    """Create a filename slug from URL."""
    parsed = urlparse(url)
    path = parsed.path.strip("/").replace("/", "_")
    if not path:
        path = "home"
    host = parsed.netloc.replace(".", "_")
    return f"{host}__{path}"

def run_axe(page):
    """Run axe-core and return results."""
    try:
        # Inject and run axe
        results = page.evaluate("""() => {
            return new Promise((resolve) => {
                if (typeof axe === 'undefined') {
                    // Try to load axe from CDN
                    const script = document.createElement('script');
                    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/axe-core/4.8.2/axe.min.js';
                    script.onload = () => {
                        axe.run({ runOnly: { type: 'tag' } }, (err, results) => {
                            if (err) resolve({ error: err.message });
                            resolve(results);
                        });
                    };
                    script.onerror = () => resolve({ error: 'axe failed to load' });
                    document.head.appendChild(script);
                } else {
                    axe.run({ runOnly: { type: 'tag' } }, (err, results) => {
                        if (err) resolve({ error: err.message });
                        resolve(results);
                    });
                }
            });
        }""")
        return results
    except Exception as e:
        return {"error": str(e)}

def check_page_elements(page, url):
    """Check for H1, alt text, heading order, links, etc."""
    data = page.evaluate("""() => {
        const result = {};

        // Title
        result.title = document.title;

        // Meta description
        const metaDesc = document.querySelector('meta[name="description"]') || document.querySelector('meta[property="og:description"]');
        result.metaDescription = metaDesc ? metaDesc.getAttribute('content') : null;

        // H1
        const h1 = document.querySelector('h1');
        result.h1 = h1 ? h1.textContent.trim() : null;
        result.h1Count = document.querySelectorAll('h1').length;

        // All headings
        const headings = [];
        document.querySelectorAll('h1,h2,h3,h4,h5,h6').forEach(h => {
            headings.push({
                tag: h.tagName.toLowerCase(),
                text: h.textContent.trim().substring(0, 100),
            });
        });
        result.headings = headings;

        // Images without alt text
        const images = [];
        document.querySelectorAll('img').forEach(img => {
            const alt = img.getAttribute('alt');
            const src = img.getAttribute('src') || img.getAttribute('data-src') || 'unknown';
            if (!alt && !img.hasAttribute('alt')) {
                images.push({
                    src: src ? src.substring(0, 200) : 'unknown',
                    alt: 'MISSING',
                    selector: 'img' + (img.id ? '#' + img.id : '') + (img.className ? '.' + img.className.split(' ').join('.') : ''),
                });
            } else if (alt === '') {
                images.push({
                    src: src ? src.substring(0, 200) : 'unknown',
                    alt: 'EMPTY',
                    selector: 'img' + (img.id ? '#' + img.id : '') + (img.className ? '.' + img.className.split(' ').join('.') : ''),
                });
            }
        });
        result.imagesMissingAlt = images;

        // Check for specific elements
        result.hasNewsletterSignup = !!document.querySelector('input[type="email"], #newsletter, .newsletter, [data-newsletter]') || 
                                     !!Array.from(document.querySelectorAll('*')).some(el => 
                                         el.textContent.toLowerCase().includes('newsletter') || 
                                         el.textContent.toLowerCase().includes('subscribe'));
        result.hasGiftVouchers = !!Array.from(document.querySelectorAll('a, button, h1,h2,h3,h4,h5,h6')).some(el => 
            el.textContent.toLowerCase().includes('gift') || el.textContent.toLowerCase().includes('voucher'));
        result.hasFAQ = !!document.querySelector('.faq, #faq, [data-faq], accordion') ||
                        !!Array.from(document.querySelectorAll('*')).some(el => el.textContent.toLowerCase().includes('faq'));
        result.hasCookieBanner = !!document.querySelector('.cookie, [class*="cookie"], .gdpr, [class*="consent"]]');
        result.hasWhatsApp = !!document.querySelector('a[href*="wa.me"], a[href*="whatsapp"]');
        result.hasContactPhone = !!document.querySelector('a[href*="tel:"]');

        // All links on page
        const links = [];
        document.querySelectorAll('a[href]').forEach(a => {
            links.push({
                href: a.href,
                text: a.textContent.trim().substring(0, 100),
            });
        });
        result.links = links;

        // Scripts
        const scripts = [];
        document.querySelectorAll('script[src]').forEach(s => {
            scripts.push(s.src);
        });
        result.scripts = scripts;

        // Viewport meta
        const viewport = document.querySelector('meta[name="viewport"]');
        result.viewport = viewport ? viewport.content : null;

        return result;
    }
    return {}
    return data

def main():
    audit_results = {}

    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True, args=["--no-sandbox", "--disable-gpu", "--disable-dev-shm-usage"])

        for url in PAGES:
            slug = slugify(url)
            print(f"Auditing: {url}")

            # Mobile audit
            page = browser.new_context(viewport=MOBILE_VIEWPORT).new_page()
            try:
                page.goto(url, wait_until="networkidle", timeout=30000)
                time.sleep(2)  # Wait for JS to settle
                page.screenshot(path=os.path.join(SHOTS_DIR, f"{slug}__mobile.png"))

                # Wait a bit more for dynamic content
                time.sleep(1)

                page_data = check_page_elements(page, url)
                mobile_axe = run_axe(page)

                audit_results[url] = {
                    "mobile": {
                        "page_data": page_data,
                        "axe_results": mobile_axe,
                    }
                }
            except Exception as e:
                audit_results[url] = {"error": str(e)}
            finally:
                page.close()

            # Desktop audit
            page = browser.new_context(viewport=DESKTOP_VIEWPORT).new_page()
            try:
                page.goto(url, wait_until="networkidle", timeout=30000)
                time.sleep(2)
                page.screenshot(path=os.path.join(SHOTS_DIR, f"{slug}__desktop.png"))
                time.sleep(1)

                page_data = check_page_elements(page, url)
                desktop_axe = run_axe(page)

                if url not in audit_results:
                    audit_results[url] = {}
                audit_results[url]["desktop"] = {
                    "page_data": page_data,
                    "axe_results": desktop_axe,
                }
            except Exception as e:
                if url not in audit_results:
                    audit_results[url] = {}
                audit_results[url]["desktop_error"] = str(e)
            finally:
                page.close()

            time.sleep(0.5)

        browser.close()

    # Save results
    with open("/root/hotbox-closer/audit/axe-results.json", "w") as f:
        json.dump(audit_results, f, indent=2, default=str)

    print("\n=== AUDIT COMPLETE ===")
    print(f"Pages audited: {len(audit_results)}")
    print(f"Results saved to: /root/hotbox-closer/audit/axe-results.json")
    print(f"Screenshots in: {SHOTS_DIR}")

if __name__ == "__main__":
    main()
